//! Assembles canonical Rust source into files grouped by semantic unit.

use std::fmt::{self, Write as _};

use chigiri_core::DiagnosticCode;

const GENERATED_HEADER: &str =
    "// This file was generated by Chigiri.\n// Do not edit manually.\n\n";

mod layout;
pub(crate) use layout::assemble_items;

#[derive(Clone, Debug, Eq, PartialEq)]
pub(crate) struct GeneratedFile {
    pub(crate) name: String,
    pub(crate) contents: String,
    pub(crate) exports_public_items: bool,
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub(crate) struct GeneratedItem {
    label: String,
    contents: String,
    exports_public_item: bool,
}

impl GeneratedItem {
    pub(crate) fn new(label: impl Into<String>, contents: impl Into<String>) -> Self {
        let mut contents = contents.into();
        if !contents.is_empty() && !contents.ends_with('\n') {
            contents.push('\n');
        }
        Self {
            label: label.into(),
            contents,
            exports_public_item: false,
        }
    }

    pub(crate) fn set_file(&mut self, path: &str) {
        self.label = path.to_owned();
    }

    pub(crate) fn in_file(mut self, path: impl Into<String>) -> Self {
        self.label = path.into();
        self
    }

    pub(crate) const fn exported(mut self) -> Self {
        self.exports_public_item = true;
        self
    }

    pub(crate) fn into_parts(self) -> (String, String, bool) {
        (self.label, self.contents, self.exports_public_item)
    }

    pub(crate) fn byte_len(&self) -> usize {
        self.contents.len()
    }
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub(crate) struct WriterError {
    pub(crate) code: DiagnosticCode,
    pub(crate) message: String,
}

impl fmt::Display for WriterError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(formatter, "{}: {}", self.code, self.message)
    }
}

impl std::error::Error for WriterError {}

/// Canonical writer that applies four-space indentation to logical lines.
#[derive(Default)]
pub(crate) struct RustWriter {
    contents: String,
    indent: usize,
}

impl RustWriter {
    pub(crate) const fn new() -> Self {
        Self {
            contents: String::new(),
            indent: 0,
        }
    }

    pub(crate) fn line(&mut self, line: &str) {
        assert!(
            !line.contains(['\n', '\r']),
            "lines must be written one at a time"
        );
        if !line.is_empty() {
            for _ in 0..self.indent {
                self.contents.push_str("    ");
            }
            self.contents.push_str(line);
        }
        self.contents.push('\n');
    }

    pub(crate) fn blank_line(&mut self) {
        self.contents.push('\n');
    }

    pub(crate) fn indented<R>(&mut self, write: impl FnOnce(&mut Self) -> R) -> R {
        self.indent += 1;
        let result = write(self);
        self.indent -= 1;
        result
    }

    pub(crate) fn doc_comment(&mut self, text: &str) {
        for line in rust_doc_comment(text).lines() {
            self.line(line);
        }
    }

    pub(crate) fn finish(mut self) -> String {
        if !self.contents.is_empty() && !self.contents.ends_with('\n') {
            self.contents.push('\n');
        }
        self.contents
    }
}

/// Returns a Rust string literal that is safe to embed in generated source.
pub(crate) fn rust_string_literal(value: &str) -> String {
    let mut output = String::with_capacity(value.len().saturating_add(2));
    output.push('"');
    for character in value.chars() {
        match character {
            '"' => output.push_str("\\\""),
            '\\' => output.push_str("\\\\"),
            '\n' => output.push_str("\\n"),
            '\r' => output.push_str("\\r"),
            '\t' => output.push_str("\\t"),
            '\0' => output.push_str("\\0"),
            character if requires_unicode_escape(character) => {
                write!(&mut output, "\\u{{{:x}}}", u32::from(character))
                    .expect("writing to String cannot fail");
            }
            character => output.push(character),
        }
    }
    output.push('"');
    output
}

/// Converts multiline text into Rust doc comments without allowing source injection.
pub(crate) fn rust_doc_comment(value: &str) -> String {
    let normalized = value.replace("\r\n", "\n").replace('\r', "\n");
    let mut output = String::new();
    for line in normalized.split('\n') {
        output.push_str("///");
        if !line.is_empty() {
            output.push(' ');
            for character in line.chars() {
                match character {
                    '\t' => output.push_str("\\t"),
                    character if requires_unicode_escape(character) => {
                        write!(&mut output, "\\u{{{:x}}}", u32::from(character))
                            .expect("writing to String cannot fail");
                    }
                    character => output.push(character),
                }
            }
        }
        output.push('\n');
    }
    output
}

/// Escapes external text for safe use in a single generated comment line.
pub(crate) fn rust_comment_text(value: &str) -> String {
    let mut output = String::new();
    for character in value.chars() {
        match character {
            '\\' => output.push_str("\\\\"),
            '\n' => output.push_str("\\n"),
            '\r' => output.push_str("\\r"),
            '\t' => output.push_str("\\t"),
            character if requires_unicode_escape(character) => {
                write!(&mut output, "\\u{{{:x}}}", u32::from(character))
                    .expect("writing to String cannot fail");
            }
            character => output.push(character),
        }
    }
    output
}

fn requires_unicode_escape(character: char) -> bool {
    character.is_control()
        || matches!(
            character,
            '\u{202a}'..='\u{202e}' | '\u{2066}'..='\u{2069}'
        )
}

#[cfg(test)]
mod tests {
    use super::{
        GeneratedItem, RustWriter, assemble_items, rust_comment_text, rust_doc_comment,
        rust_string_literal,
    };

    fn lines(count: usize) -> String {
        "pub(crate) const VALUE: usize = 1;\n".repeat(count)
    }

    #[test]
    fn writer_paths_and_semantic_paths_are_byte_identical_for_the_same_input() {
        let mut writer = RustWriter::new();
        writer.doc_comment("The resulting function.");
        writer.line("pub(crate) fn value() {");
        writer.indented(|writer| writer.line("let value = 1;"));
        writer.line("}");
        writer.blank_line();
        let items = vec![GeneratedItem::new("types/value.rs", writer.finish())];

        let first = assemble_items(items.clone()).unwrap();
        let second = assemble_items(items).unwrap();
        assert_eq!(first, second);
        assert_eq!(first[0].name, "types/value.rs");
        assert!(first[0].contents.contains("    let value = 1;"));
        assert!(first[0].contents.ends_with('\n'));
    }

    #[test]
    fn rejects_duplicate_owners_and_conflicting_paths_or_bytes() {
        let stable = GeneratedItem::new("types/stable.rs", "pub struct Stable;");
        let small = assemble_items([stable.clone()]).unwrap();
        let files = assemble_items([
            GeneratedItem::new("types/large.rs", lines(450)),
            stable,
            GeneratedItem::new("types/large.rs", "pub struct Tail;"),
        ])
        .unwrap();
        assert_eq!(files.len(), 2);
        assert_eq!(files[1], small[0]);
        assert!(files[0].contents.lines().count() > 450);
        assert!(files[0].contents.contains("pub struct Tail;"));
    }

    #[test]
    fn repeated_single_items_remain_within_the_four_hundred_line_limit() {
        let files = assemble_items([GeneratedItem::new("types/huge.rs", lines(398))]).unwrap();
        assert_eq!(files.len(), 1);
        assert_eq!(files[0].contents.lines().count(), 401);
    }

    #[test]
    fn safely_escapes_strings_and_doc_comment_control_characters() {
        assert_eq!(
            rust_string_literal("Day\"\\\n\t\0"),
            "\"Day\\\"\\\\\\n\\t\\0\""
        );
        assert_eq!(
            rust_doc_comment("Line\r\nTwo\t\u{7}"),
            "/// Line\n/// Two\\t\\u{7}\n"
        );
        assert_eq!(rust_string_literal("a\u{202e}b"), "\"a\\u{202e}b\"");
        assert_eq!(rust_doc_comment("a\u{2066}b"), "/// a\\u{2066}b\n");
        assert_eq!(rust_comment_text("a\n\u{202d}"), "a\\n\\u{202d}");
        assert_ne!(rust_comment_text("a\nb"), rust_comment_text("a\\nb"));
    }
}
